<script setup lang="ts">
import { ref } from 'vue'; import { useI18n } from 'vue-i18n'; import UpdatePlan from '../components/UpdatePlan.vue'; import DiscoverWizard from '../components/DiscoverWizard.vue'; import LogPanel from '../components/LogPanel.vue'; import { api, runApi, state } from '../composables/useApi';
const { t } = useI18n(); const tab = ref('skill'); const selected = ref<string[]>([]);
const updateSkills = () => runApi(() => api('/api/update/skills', { method: 'POST', body: JSON.stringify({ skills: selected.value }) }));
const updateSource = (key: string) => runApi(() => api('/api/update/source', { method: 'POST', body: JSON.stringify({ key }) }));
</script><template><section class="page-head"><h1>{{ t('updates.title') }}</h1></section><div class="tabs"><button @click="tab='skill'">{{ t('updates.bySkill') }}</button><button @click="tab='source'">{{ t('updates.bySource') }}</button><button @click="tab='url'">{{ t('updates.fromUrl') }}</button></div><section v-if="tab==='skill'" class="card"><h2>{{ t('updates.plan') }}</h2><div class="toolbar"><label v-for="c in state?.candidates" :key="c.skill"><input v-model="selected" :value="c.skill" type="checkbox"> {{ c.skill }}</label><button :disabled="!selected.length" @click="updateSkills">{{ t('common.update') }}</button></div><UpdatePlan :candidates="state?.candidates || []" /></section><section v-if="tab==='source'" class="cards"><article v-for="s in state?.sources" :key="s.key" class="card"><h3>{{ s.url }}</h3><p>{{ s.skills.map(x=>x.skill).join(', ') }}</p><button @click="updateSource(s.key)">{{ t('common.update') }}</button></article></section><section v-if="tab==='url'"><DiscoverWizard /></section><p class="muted">{{ t('common.gitDiffNext') }}</p><LogPanel /></template>
